# BFS restricted to wall bounding box, rows 5..11 and cols 8..16 inclusive zero-based
cand=[r[:] for r in grid]; q=deque([(8,14)]); seen={(8,14)}
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 5<=rr<=11 and 8<=cc<=16 and (rr,cc) not in seen and cand[rr][cc]==1:
   seen.add((rr,cc));cand[rr][cc]=2;q.append((rr,cc))
print('\n'.join(' '.join(map(str,r)) for r in cand))
print(cand)
